func test_lineage_TestLineage_test_subquery(self *Case, a Args) Value {
	var node, a_, b Value
	_ = []Value{node, a_, b}
	self.DoAssign(346, func() {
		node = Call(G("sqlglot.lineage.lineage"), "output", "SELECT (SELECT max(t3.my_column) my_column FROM foo t3) AS output FROM table3", Kw("schema", NewDict("foo", NewDict("my_column", "INT"))))
	}, &node)
	self.Do(351, func() { self.AssertEqual(A(node, "name"), "output") })
	self.DoAssign(352, func() { node = Item(A(node, "downstream"), 0) }, &node)
	self.Do(353, func() { self.AssertEqual(A(node, "name"), "my_column") })
	self.DoAssign(354, func() { node = Item(A(node, "downstream"), 0) }, &node)
	self.Do(355, func() { self.AssertEqual(A(node, "name"), "t3.my_column") })
	self.Do(356, func() { self.AssertEqual(M(A(node, "source"), "sql"), "foo AS t3") })
	self.DoAssign(358, func() {
		node = Call(G("sqlglot.lineage.lineage"), "y", "SELECT SUM((SELECT max(a) a from x) + (SELECT min(b) b from x) + c) AS y FROM x", Kw("schema", NewDict("x", NewDict("a", "INT", "b", "INT", "c", "INT"))))
	}, &node)
	self.Do(363, func() { self.AssertEqual(A(node, "name"), "y") })
	self.Do(364, func() { self.AssertEqual(Len(A(node, "downstream")), 3) })
	self.Do(365, func() { self.AssertEqual(A(Item(A(node, "downstream"), 0), "name"), "a") })
	self.Do(366, func() { self.AssertEqual(A(Item(A(node, "downstream"), 1), "name"), "b") })
	self.Do(367, func() { self.AssertEqual(A(Item(A(node, "downstream"), 2), "name"), "x.c") })
	self.DoAssign(369, func() {
		node = Call(G("sqlglot.lineage.lineage"), "x", "WITH cte AS (SELECT a, b FROM z) SELECT sum(SELECT a FROM cte) AS x, (SELECT b FROM cte) as y FROM cte", Kw("schema", NewDict("z", NewDict("a", "INT", "b", "INT"))))
	}, &node)
	self.Do(374, func() { self.AssertEqual(A(node, "name"), "x") })
	self.Do(375, func() { self.AssertEqual(Len(A(node, "downstream")), 1) })
	self.DoAssign(376, func() { node = Item(A(node, "downstream"), 0) }, &node)
	self.Do(377, func() { self.AssertEqual(A(node, "name"), "a") })
	self.DoAssign(378, func() { node = Item(A(node, "downstream"), 0) }, &node)
	self.Do(379, func() { self.AssertEqual(A(node, "name"), "cte.a") })
	self.Do(380, func() { self.AssertEqual(A(node, "reference_node_name"), "cte") })
	self.DoAssign(381, func() { node = Item(A(node, "downstream"), 0) }, &node)
	self.Do(382, func() { self.AssertEqual(A(node, "name"), "z.a") })
	self.DoAssign(384, func() {
		node = Call(G("sqlglot.lineage.lineage"), "a", "\n            WITH foo AS (\n              SELECT\n                1 AS a\n            ), bar AS (\n              (\n                SELECT\n                  a + 1 AS a\n                FROM foo\n              )\n            )\n            (\n              SELECT\n                a + b AS a\n              FROM bar\n              CROSS JOIN (\n                SELECT\n                  2 AS b\n              ) AS baz\n            )\n            ", Kw("schema", NewDict()))
	}, &node)
	self.Do(409, func() { self.AssertEqual(A(node, "name"), "a") })
	self.Do(410, func() { self.AssertEqual(Len(A(node, "downstream")), 2) })
	self.DoAssign(411, func() {
		Unpack(Call(G("sorted"), A(node, "downstream"), Kw("key", Lambda(func(args ...Value) Value {
			var n Value = nil
			if len(args) > 0 {
				n = args[0]
			}
			_ = n
			return A(n, "name")
		}))), &a_, &b)
	}, &a_, &b)
	self.Do(412, func() { self.AssertEqual(A(a_, "name"), "bar.a") })
	self.Do(413, func() { self.AssertEqual(Len(A(a_, "downstream")), 1) })
	self.Do(414, func() { self.AssertEqual(A(b, "name"), "baz.b") })
	self.Do(415, func() { self.AssertEqual(A(b, "downstream"), NewList()) })
	self.DoAssign(417, func() { node = Item(A(a_, "downstream"), 0) }, &node)
	self.Do(418, func() { self.AssertEqual(A(node, "name"), "foo.a") })
	self.DoAssign(421, func() {
		node = Call(G("sqlglot.lineage.lineage"), "a", "SELECT a FROM (SELECT a FROM x) subquery", Kw("schema", NewDict("x", NewDict("a", "INT"))))
	}, &node)
	self.Do(426, func() { self.AssertEqual(A(node, "name"), "a") })
	self.Do(427, func() { self.AssertEqual(Len(A(node, "downstream")), 1) })
	self.DoAssign(428, func() { node = Item(A(node, "downstream"), 0) }, &node)
	self.Do(429, func() { self.AssertEqual(A(node, "name"), "subquery.a") })
	self.Do(430, func() { self.AssertEqual(A(node, "reference_node_name"), "subquery") })
	self.DoAssign(432, func() {
		node = Call(G("sqlglot.lineage.lineage"), "a", "SELECT a FROM (SELECT a FROM x)", Kw("schema", NewDict("x", NewDict("a", "INT"))))
	}, &node)
	self.Do(437, func() { self.AssertEqual(A(node, "name"), "a") })
	self.Do(438, func() { self.AssertEqual(Len(A(node, "downstream")), 1) })
	self.DoAssign(439, func() { node = Item(A(node, "downstream"), 0) }, &node)
	self.Do(440, func() { self.AssertEqual(A(node, "name"), "_0.a") })
	self.Do(441, func() { self.AssertEqual(A(node, "reference_node_name"), "_0") })
	return nil
}

