func test_lineage_TestLineage_test_lineage_no_self_loops_with_multi_aliased_union_cte(self *Case, a Args) Value {
	var query, node, visited, stack, current, path, child Value
	_ = []Value{query, node, visited, stack, current, path, child}
	self.DoAssign(489, func() {
		query = "\n        WITH three_way AS (\n            SELECT a FROM t1\n            UNION ALL\n            SELECT a FROM t2\n            UNION ALL\n            SELECT a FROM t3\n        ),\n        attached AS (\n            SELECT COALESCE(r1.a, r2.a) AS a\n            FROM three_way AS r1\n            LEFT JOIN three_way AS r2 ON r1.a = r2.a\n        )\n        SELECT a FROM attached\n        "
	}, &query)
	self.DoAssign(505, func() {
		node = Call(G("sqlglot.lineage.lineage"), "a", query, Kw("schema", NewDict("t1", NewDict("a", "INT"), "t2", NewDict("a", "INT"), "t3", NewDict("a", "INT"))))
	}, &node)
	self.Do(509, func() { visited = Call(G("set")) })
	self.DoAssign(510, func() { stack = NewList(NewTuple(node, Call(G("frozenset"), NewList(Call(G("id"), node))))) }, &stack)
	for Truth(stack) {
		self.DoAssign(512, func() { Unpack(M(stack, "pop"), &current, &path) }, &current, &path)
		if Truth(In(Call(G("id"), current), visited)) {
			continue
		}
		self.Do(515, func() { Stmt(M(visited, "add", Call(G("id"), current))) })
		for _, item_ := range Iter(A(current, "downstream")) {
			child = item_
			self.Do(517, func() {
				Stmt(M(self, "assertNotIn", Call(G("id"), child), path, F("cycle detected at node '", FV{V: A(child, "name")}, "'")))
			})
			self.Do(522, func() { Stmt(M(stack, "append", NewTuple(child, BitOp(path, NewSet(Call(G("id"), child)), "|")))) })
		}
	}
	return nil
}

