func test_lineage_TestLineage_test_lineage_shared_cte_performance(self *Case, a Args) Value {
	var n_levels, ctes, k, prev, sql, node, all_nodes, all_ids, leaves Value
	_ = []Value{n_levels, ctes, k, prev, sql, node, all_nodes, all_ids, leaves}
	self.DoAssign(1171, func() { n_levels = 12 }, &n_levels)
	self.DoAssign(1172, func() { ctes = NewList("cte_0 AS (SELECT a FROM base_table)") }, &ctes)
	for _, item_ := range Iter(Call(G("range"), 1, n_levels)) {
		k = item_
		self.DoAssign(1174, func() { prev = F("cte_", FV{V: Sub(k, 1)}) }, &prev)
		self.Do(1175, func() {
			Stmt(M(ctes, "append", F("cte_", FV{V: k}, " AS (SELECT t1.a + t2.a AS a FROM ", FV{V: prev}, " t1 JOIN ", FV{V: prev}, " t2 ON t1.a = t2.a)")))
		})
	}
	self.DoAssign(1178, func() {
		sql = Add(Add("WITH ", M(",\n     ", "join", ctes)), F("\nSELECT a FROM cte_", FV{V: Sub(n_levels, 1)}))
	}, &sql)
	self.DoAssign(1180, func() {
		node = Call(G("sqlglot.lineage.lineage"), "a", sql, Kw("schema", NewDict("base_table", NewDict("a", "int"))))
	}, &node)
	self.DoAssign(1183, func() { all_nodes = Call(G("list"), M(node, "walk")) }, &all_nodes)
	self.Do(1186, func() {
		Stmt(M(self, "assertLess", Len(all_nodes), 200, F("got ", FV{V: Len(all_nodes)}, " nodes -- DAG walk may be broken")))
	})
	self.DoAssign(1193, func() {
		all_ids = func() Value {
			var n Value
			_ = []Value{n}
			var out []Value
			for _, item_ := range Iter(all_nodes) {
				n = item_
				out = append(out, Call(G("id"), n))
			}
			return &List{V: out}
		}()
	}, &all_ids)
	self.Do(1194, func() { self.AssertEqual(Len(all_ids), Len(Call(G("set"), all_ids))) })
	self.DoAssign(1197, func() {
		leaves = func() Value {
			var n Value
			_ = []Value{n}
			var out []Value
			for _, item_ := range Iter(all_nodes) {
				n = item_
				if Truth(Not(A(n, "downstream"))) {
					out = append(out, n)
				}
			}
			return &List{V: out}
		}()
	}, &leaves)
	self.Do(1198, func() { Stmt(M(self, "assertGreater", Len(leaves), 0)) })
	self.Do(1199, func() {
		Stmt(M(self, "assertTrue", Call(G("all"), func() Value {
			var n Value
			_ = []Value{n}
			var out []Value
			for _, item_ := range Iter(leaves) {
				n = item_
				out = append(out, In("base_table", M(A(n, "source"), "sql")))
			}
			return &List{V: out}
		}())))
	})
	return nil
}

