func test_lineage_TestLineage_test_lineage_on_node_fires_once_per_node(self *Case, a Args) Value {
	var counts, hook, result, seen, top, node, nid Value
	_ = []Value{counts, hook, result, seen, top, node, nid}
	self.Do(1352, func() { counts = NewDict() })
	self.Do(1354, func() {
		hook = Func("hook", func(a Args) Value {
			node = a.Get(0, "node", nil)
			SetItem(counts, Call(G("id"), node), Add(M(counts, "get", Call(G("id"), node), 0), 1))
			return nil
		})
	})
	self.DoAssign(1357, func() {
		result = Call(G("sqlglot.lineage.lineage"), nil, "WITH t AS (SELECT a, b FROM x) SELECT a, a + b AS ab FROM t", Kw("schema", NewDict("x", NewDict("a", "int", "b", "int"))), Kw("on_node", hook))
	}, &result)
	self.Do(1366, func() { seen = Call(G("set")) })
	for _, item_ := range Iter(M(result, "values")) {
		top = item_
		for _, item_ := range Iter(M(top, "walk")) {
			node = item_
			self.Do(1369, func() { Stmt(M(seen, "add", Call(G("id"), node))) })
		}
	}
	for _, item_ := range Iter(seen) {
		nid = item_
		self.Do(1371, func() { self.AssertEqual(M(counts, "get", nid, 0), 1) })
	}
	return nil
}
